#!/usr/bin/env python3
"""Regression checks using real fixture-byte mutations and fresh pinned dumps."""
from pathlib import Path
import runpy
import shutil
import struct
import subprocess
import tempfile
from unittest.mock import patch

HERE = Path(__file__).resolve().parent
api = runpy.run_path(str(HERE / "fixture_tools.py"))


def replace_word(data, offset, old, new):
    assert struct.unpack_from("<I", data, offset)[0] == old
    struct.pack_into("<I", data, offset, new)


def check(work, source, label, data=None, rejection=None):
    macho = source.parent.name == "code-macho"
    family = "macho" if macho else "elf"
    (work / label).write_bytes(source.read_bytes() if data is None else data)
    b = api["Build"](family, work)
    d = b.dumps(label, macho)
    try:
        api["oracle"](b, label, "x86_64" if source.name.startswith("x86") else "arm64",
                      d, macho=macho, obj=macho)
    except AssertionError as error:
        if rejection is None or rejection not in str(error):
            raise
        print(f"REJECT {label}: {error}")
    else:
        assert rejection is None, f"false accept: {label} -> {b.rows}"
        assert b.rows and any(row[6] in ("connect", "_connect") for row in b.rows)
        print(f"ACCEPT {label}: {len(b.rows)} oracle rows")


def regressions(work):
    macho = HERE.parent / "code-macho"
    for name in ("elf-clang-got.so", "elf-gcc-got.so", "elf-clang-plt.so", "elf-gcc-plt.so", "elf-cases.so"):
        check(work, HERE / name, "original-" + name)
    for name in ("arm64-object.o", "x86-object.o", "arm64-cases.o", "x86-cases.o", "compact-object.o"):
        check(work, macho / name, "original-" + name)

    got = HERE / "elf-clang-got.so"
    for label, edits in (
        ("wrong-register-got.so", [(0x370, 0xd63f0100, 0xd63f0120), (0x39c, 0xd63f0100, 0xd63f0120)]),
        ("wrong-slot-got.so", [(0x368, 0xf9422908, 0xf9422d08)]),
        ("clobbered-register-got.so", [(0x36c, 0x2a1f03e2, 0x2a1f03e8)]),
    ):
        data = bytearray(got.read_bytes())
        for offset, old, new in edits:
            replace_word(data, offset, old, new)
        check(work, got, label, data, "ELF")

    plt = HERE / "elf-clang-plt.so"
    for label, offset, old, new in (
        ("wrong-target-plt.so", 0x3a0, 0x94000018, 0x94000019),
        ("wrong-slot-plt.so", 0x404, 0xf9426e11, 0xf9427211),
    ):
        data = bytearray(plt.read_bytes())
        replace_word(data, offset, old, new)
        check(work, plt, label, data, "ELF")
    data = bytearray(plt.read_bytes())
    replace_word(data, 0x404, 0xf9426e11, 0xf9427211)
    replace_word(data, 0x408, 0x91136210, 0x91138210)
    check(work, plt, "consistent-wrong-slot-plt.so", data, "ELF")

    b = api["Build"]("elf", work)
    d = b.dumps("original-elf-clang-got.so")
    relocation = api["section"](d, ".rela.dyn")["Offset"]
    data = bytearray(got.read_bytes())
    assert struct.unpack_from("<q", data, relocation + 16)[0] == 0
    struct.pack_into("<q", data, relocation + 16, 1)
    check(work, got, "nonzero-addend-got.so", data, "ELF")
    data = bytearray(got.read_bytes())
    info = struct.unpack_from("<Q", data, relocation + 8)[0]
    assert info >> 32 == 1
    struct.pack_into("<Q", data, relocation + 8, info & 0xffffffff)
    check(work, got, "wrong-symbol-got.so", data, "ELF")

    compact = macho / "compact-object.o"
    original = compact.read_bytes()
    info = struct.unpack_from("<I", original, 0x224)[0]
    assert info & 0xffffff == 1 and (info >> 25) & 3 == 3
    for label, changes in (
        ("nontext-compact.o", [(0x224, (info & 0xff000000) | 2), (0x22c, (info & 0xff000000) | 2)]),
        ("wrong-width-compact.o", [(0x224, (info & ~(3 << 25)) | (2 << 25))]),
        ("pcrel-compact.o", [(0x224, info | (1 << 24))]),
        ("external-compact.o", [(0x224, info | (1 << 27))]),
        ("wrong-type-compact.o", [(0x224, info | (1 << 28))]),
        ("misplaced-compact.o", [(0x220, 0x28)]),
        ("duplicate-compact.o", [(0x228, 0x20)]),
        ("oversized-compact.o", [(0x1d8, 0x1000)]),
        ("nonfunction-start-compact.o", [(0x1d0, 4)]),
    ):
        data = bytearray(original)
        for offset, value in changes:
            struct.pack_into("<I", data, offset, value)
        check(work, compact, label, data, "compact")


def publication(work):
    source = work / "publish-source"
    source.mkdir()
    (source / "a.bin").write_bytes(b"new-a")
    (source / "b.bin").write_bytes(b"new-b")
    existing = work / "existing-user-output"
    existing.mkdir()
    (existing / "user.txt").write_bytes(b"preserve me")
    (existing / "stale.o").write_bytes(b"not generated by this run")
    original = {p.name: p.read_bytes() for p in existing.iterdir()}
    b = api["Build"]("elf", source)
    b.files = ["a.bin", "b.bin"]
    try:
        b.finish(existing)
    except FileExistsError:
        pass
    else:
        raise AssertionError("existing output unexpectedly accepted")
    assert original == {p.name: p.read_bytes() for p in existing.iterdir()}

    dest = work / "failed-publication"
    copyfile = shutil.copyfile
    copies = 0

    def fail_second_copy(*args, **kwargs):
        nonlocal copies
        copies += 1
        if copies == 2:
            raise OSError("injected second-copy failure")
        return copyfile(*args, **kwargs)

    with patch.object(shutil, "copyfile", fail_second_copy):
        try:
            b.finish(dest)
        except OSError as error:
            assert "injected" in str(error)
        else:
            raise AssertionError("injected publication failure unexpectedly succeeded")
    assert not dest.exists() and not list(work.glob(".sigil-publish-*"))
    fresh = api["Build"]("elf", source)
    fresh.files = ["a.bin", "b.bin"]
    fresh.finish(work / "complete-publication")
    assert original == {p.name: p.read_bytes() for p in existing.iterdir()}
    print("PASS publication: existing files preserved, failed copy exposes no output, fresh publication succeeds")

    old = work / "refresh-destination"
    shutil.copytree(work / "complete-publication", old)
    (old / "user.txt").write_bytes(b"preserve user source")
    (source / "a.bin").write_bytes(b"updated-a")
    updated = api["Build"]("elf", source)
    updated.files = ["a.bin", "b.bin"]
    updated.finish(work / "refresh-input")
    original = {p.name: p.read_bytes() for p in old.iterdir()}
    replace = api["os"].replace
    replacements = 0

    def fail_second_replace(*args, **kwargs):
        nonlocal replacements
        replacements += 1
        if replacements == 2:
            raise OSError("injected second-replace failure")
        return replace(*args, **kwargs)

    with patch.object(api["os"], "replace", fail_second_replace):
        try:
            api["refresh_generated"](work / "refresh-input", old)
        except OSError as error:
            assert "injected" in str(error)
        else:
            raise AssertionError("injected refresh failure unexpectedly succeeded")
    assert original == {p.name: p.read_bytes() for p in old.iterdir()}
    api["refresh_generated"](work / "refresh-input", old)
    assert (old / "a.bin").read_bytes() == b"updated-a" and (old / "user.txt").read_bytes() == original["user.txt"]
    print("PASS refresh: failed promotion fully rolled back; successful refresh preserves user files")
    saved = (old / "a.bin").read_bytes()
    (old / "a.bin").write_bytes(b"local user edit")
    try:
        api["refresh_generated"](work / "refresh-input", old)
    except AssertionError as error:
        assert "changed generated file" in str(error)
    else:
        raise AssertionError("locally edited generated file was overwritten")
    assert (old / "a.bin").read_bytes() == b"local user edit"
    (old / "a.bin").write_bytes(saved)
    extra = work / "changed-inventory"
    shutil.copytree(work / "refresh-input", extra)
    (extra / "extra.o").write_bytes(b"new inventory member")
    with (extra / "SHA256SUMS").open("a") as manifest:
        manifest.write(api["sha"](extra / "extra.o") + "  extra.o\n")
    try:
        api["refresh_generated"](extra, old)
    except AssertionError as error:
        assert "inventory changed" in str(error)
    else:
        raise AssertionError("changed inventory was silently merged")
    for folder in (HERE, HERE.parent / "code-macho"):
        result = subprocess.run([str(folder / "build.sh")], capture_output=True, text=True)
        assert result.returncode == 2 and "Usage:" in result.stderr
        result = subprocess.run([str(folder / "build.sh"), str(existing)], capture_output=True, text=True)
        assert result.returncode == 1 and "Destination already exists:" in result.stderr
    assert original["user.txt"] == (old / "user.txt").read_bytes()
    print("PASS maintenance guards: edits/inventory changes rejected; both build scripts require fresh explicit destinations")


if __name__ == "__main__":
    if not __debug__:
        raise RuntimeError("regression checks require Python assertions enabled")
    api["verify"]("elf")
    api["verify"]("macho")
    with tempfile.TemporaryDirectory(prefix="oracle-regression-", dir=api["ROOT"] / "target/tmp/issue48") as directory:
        work = Path(directory)
        regressions(work)
        publication(work)
    print("PASS: 10 original inputs accepted, 17 actual binary mutations rejected, publication/refresh fault checks passed")
